sys_variable_value.value:
(function() {
    var outputs_obj = {
        ai_answer: '',
        status: 'success',
        full_history_json: ''
    };

    try {
        var helper = new x_1815796_itsmgr_0.AiBotHelper();
        
        // 1. Defensive Check: Ensure Chat ID exists
        var chat_id = (inputs.chat_id) ? inputs.chat_id.toString().trim() : "";

        if (!chat_id) {
            outputs_obj.status = 'error';
            outputs_obj.ai_answer = "Error: This action requires an existing Chat ID.";
            return;
        }

        // 2. Defensive Check: Ensure Prompt is not empty
        var prompt = (inputs.prompt) ? inputs.prompt.toString().trim() : "";
        if (!prompt) {
            outputs_obj.status = 'error';
            outputs_obj.ai_answer = "Error: Prompt cannot be empty.";
            return;
        }

        // 3. Defensive Check: Handle empty file_ids
        var file_ids = (inputs.file_ids) ? inputs.file_ids.toString().trim() : "";

        // Run the sequence: Call Bot -> Update Session -> Retrieve History
        var process = helper.processChatUpdateAndRetrieve(
            chat_id,
            prompt,
            inputs.model || "gemma3:27b",
            file_ids
        );

        // 4. Validate the 'process' result object
        if (!process) {
            outputs_obj.status = 'error';
            outputs_obj.ai_answer = "Error: The AI Helper returned a null result.";
        } else if (process.error) {
            outputs_obj.status = 'error';
            outputs_obj.ai_answer = process.error;
        } else {
            // Success Path: Capture the response and the history
            outputs_obj.ai_answer = process.ai_response || "Warning: AI returned an empty response.";
            outputs_obj.full_history_json = (process.full_history) ? JSON.stringify(process.full_history) : "[]";
        }

    } catch (ex) {
        outputs_obj.status = 'error';
        outputs_obj.ai_answer = "Action Exception: " + ex.message;
    }

    // Final Mapping to Action Outputs
    outputs.ai_answer = outputs_obj.ai_answer;
    outputs.status = outputs_obj.status;
    outputs.full_history_json = outputs_obj.full_history_json;

})();

